<?php
declare(strict_types=1);namespace App\Command;
use App\Imperium\Runtime\Conscription\OperationalManifestationSeatBindingService;use Symfony\Component\Console\Attribute\AsCommand;use Symfony\Component\Console\Command\Command;use Symfony\Component\Console\Input\InputArgument;use Symfony\Component\Console\Input\InputInterface;use Symfony\Component\Console\Input\InputOption;use Symfony\Component\Console\Output\OutputInterface;
#[AsCommand(name:'imperium:conscription:bind-operational-manifestation',description:'Atomically bind one exact operational Manifestation to its pre-derived Seat.')]
final class ConscriptionBindOperationalManifestationCommand extends Command{public function __construct(private readonly OperationalManifestationSeatBindingService$s){parent::__construct();}protected function configure():void{$this->addArgument('assembly-id',InputArgument::REQUIRED)->addOption('json',null,InputOption::VALUE_NONE);}protected function execute(InputInterface$i,OutputInterface$o):int{try{$r=$this->s->bind((string)$i->getArgument('assembly-id'));}catch(\Throwable$e){$o->writeln('<error>REFUSED</error> '.$e->getMessage());return self::FAILURE;}$o->writeln($i->getOption('json')?json_encode($r,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR):'<info>OPERATIONAL_MANIFESTATION_BOUND</info> '.$r['binding_id']);return self::SUCCESS;}}
